import math

def f0(x,y):
    return max(0.0, 0.2-abs(x-0.5)-abs(y-0.5))

def f1(x,y):
    return max(0.0, 0.2-math.hypot(x-0.5,y-0.5))
d=32
for name,f in [('diamond',f0),('disk',f1)]:
    image=[f(0.5*j/d-0.25,0.5*l/d-0.25) for j in range(1,d+1) for l in range(1,d+1)]
    print(name, 'nonzero pixels under xi=xi_prime=0.5, tau=tau_prime=0.25:',sum(v>0 for v in image))
    for xi in [-1,0,0.25,1]:
        norm2=sum(f(xi*j/d, l/d)**2 for j in range(1,d+1) for l in range(1,d+1))
        print('filter scale', xi, 'squared denominator:',norm2)
print('Squared softmax loss on one correctly classified observation, increasing logit margin:')
for t in [1,2,4,8,16]:
    print(t,(1/(1+math.exp(t)))**2)
PY"
